import { useMemo, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import StartScreen from "./StartScreen";
import Footer from "./Footer";
import "./StartQuiz.css";

function Quiz({ quizzes = [] }) {
  const { id } = useParams();
  const navigate = useNavigate();

  // 1) znajdź quiz po id z URL
  const quiz = useMemo(() => {
    return quizzes.find((q) => String(q.id) === String(id));
  }, [quizzes, id]);

  // 2) stan startu i dane ucznia
  const [started, setStarted] = useState(false);
  const [studentName, setStudentName] = useState(() => {
    try {
      return window.localStorage.getItem("quiz_student_name") || "";
    } catch {
      return "";
    }
  });

  // 3) logika pytań
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answersByIndex, setAnswersByIndex] = useState({}); // { [questionIndex]: selectedIndex }
  const [score, setScore] = useState(0);
  const [finished, setFinished] = useState(false);

  // Zabezpieczenia
  if (!quiz) return <p>Nie znaleziono quizu.</p>;

  // DOPASUJ: skąd bierzesz pytania
  const questions = quiz.questionsData ?? quiz.questions ?? [];

  if (!started) {
    return (
      <StartScreen
        nameQuiz={quiz.title}
        defaultName={studentName}
        onStart={(name) => {
          setStudentName(name);
          setStarted(true);
        }}
      />
    );
  }

  if (!Array.isArray(questions) || questions.length === 0) {
    return <p>Ten quiz nie ma pytań (brak danych w JSON).</p>;
  }

  const currentQuestion = questions[currentIndex];
  const selected = answersByIndex[currentIndex]; // undefined, jeśli nie odpowiedziano

  const handleSelectAnswer = (selectedIndex) => {
    // brak cofania: jeśli już odpowiedziałeś na to pytanie, ignorujemy klik
    if (selected !== undefined) return;

    setAnswersByIndex((prev) => ({
      ...prev,
      [currentIndex]: selectedIndex,
    }));

    // nalicz punkt od razu
    if (selectedIndex === currentQuestion.correctIndex) {
      setScore((s) => s + 1);
    }
  };

  const handleNext = () => {
    if (selected === undefined) return; // wymuś odpowiedź
    if (currentIndex >= questions.length - 1) {
      setFinished(true);
      return;
    }
    setCurrentIndex((i) => i + 1);
  };

  const handleRestart = () => {
    setCurrentIndex(0);
    setAnswersByIndex({});
    setScore(0);
    setFinished(false);
    setStarted(false); // wróć do StartScreen (opcjonalnie)
  };

  if (finished) {
    const total = questions.length;
    const percent = Math.round((score / total) * 100);

    return (
      <div className="maturazinformatyki-quiz">
        <main className="maturazinformatyki-quiz-container">
          <h1>{quiz.title}</h1>
          <p>Uczestnik: {studentName || "Anonim"}</p>

          <h2>Wynik</h2>
          <p>
            {score} / {total} ({percent}%)
          </p>

          <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
            <button type="button" onClick={handleRestart}>
              Rozwiąż ponownie
            </button>
            <button type="button" onClick={() => navigate("/")}>
              Wróć do listy quizów
            </button>
          </div>
        </main>
        <Footer nameQuiz={quiz.title} />
      </div>
    );
  }

  return (
    <div className="maturazinformatyki-quiz">
      <main className="maturazinformatyki-quiz-container">
        <h1>{quiz.title}</h1>

        <div style={{ margin: "10px 0" }}>
          <strong>Pytanie {currentIndex + 1}</strong> / {questions.length}
        </div>

        <div className="maturazinformatyki-quiz-question">
          <p style={{ fontSize: 18 }}>
            {currentQuestion.question}
          </p>
        </div>

        <div className="maturazinformatyki-quiz-answers" style={{ display: "grid", gap: 10 }}>
          {currentQuestion.answers?.map((text, idx) => {
            const isChosen = selected === idx;
            const disabled = selected !== undefined;

            return (
              <button
                key={idx}
                type="button"
                onClick={() => handleSelectAnswer(idx)}
                disabled={disabled}
                style={{
                  padding: "12px 14px",
                  textAlign: "left",
                  cursor: disabled ? "default" : "pointer",
                  opacity: disabled && !isChosen ? 0.7 : 1,
                  border: isChosen ? "2px solid #111" : "1px solid #ddd",
                  borderRadius: 10,
                  background: "#fff",
                }}
              >
                <strong>{String.fromCharCode(65 + idx)}.</strong> {text}
              </button>
            );
          })}
        </div>

        <div style={{ marginTop: 16, display: "flex", gap: 12 }}>
          <button
            type="button"
            onClick={handleNext}
            disabled={selected === undefined}
          >
            {currentIndex === questions.length - 1 ? "Zakończ" : "Dalej"}
          </button>
        </div>
      </main>

      <Footer nameQuiz={quiz.title} />
    </div>
  );
}

export default Quiz;

